import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  tasks: defineTable({
    text: v.string(),
    status: v.union(v.literal("todo"), v.literal("done")),
    runId: v.string(),
  }).index("by_run_id_and_status", ["runId", "status"]),
});

import { mutation, query } from "convex/server";
import { v } from "convex/values";

const statusValues = v.union(v.literal("todo"), v.literal("done"));

export const getTasks = query({
  args: {
    runId: v.string(),
    status: v.optional(statusValues),
  },
  handler: async (ctx, args) => {
    if (args.status) {
      return ctx.db
        .query("tasks")
        .withIndex("by_run_id_and_status", (q) =>
          q.eq("runId", args.runId).eq("status", args.status),
        )
        .collect();
    }

    return ctx.db
      .query("tasks")
      .filter((q) => q.eq(q.field("runId"), args.runId))
      .collect();
  },
});

export const addTask = mutation({
  args: {
    text: v.string(),
    runId: v.string(),
  },
  handler: async (ctx, args) => {
    return ctx.db.insert("tasks", {
      text: args.text,
      status: "todo",
      runId: args.runId,
    });
  },
});

export const updateTaskStatus = mutation({
  args: {
    id: v.id("tasks"),
    status: statusValues,
  },
  handler: async (ctx, args) => {
    await ctx.db.patch(args.id, { status: args.status });
  },
});

export const deleteTask = mutation({
  args: {
    id: v.id("tasks"),
  },
  handler: async (ctx, args) => {
    await ctx.db.delete(args.id);
  },
});

import { FormEvent, useMemo, useState } from 'react'
import { useMutation, useQuery } from 'convex/react'
import { api } from '../convex/_generated/api'
import './App.css'

type StatusFilter = 'all' | 'todo' | 'done'

function App() {
  const runId = import.meta.env.VITE_ZEALT_RUN_ID ?? 'local'
  const [text, setText] = useState('')
  const [filter, setFilter] = useState<StatusFilter>('all')

  const statusArg = useMemo(() => {
    if (filter === 'all') {
      return undefined
    }
    return filter
  }, [filter])

  const tasks = useQuery(api.tasks.getTasks, {
    runId,
    status: statusArg,
  })
  const addTask = useMutation(api.tasks.addTask)
  const updateTaskStatus = useMutation(api.tasks.updateTaskStatus)
  const deleteTask = useMutation(api.tasks.deleteTask)

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault()
    const trimmed = text.trim()
    if (!trimmed) {
      return
    }
    await addTask({ text: trimmed, runId })
    setText('')
  }

  return (
    <div className="app">
      <header>
        <div>
          <h1>Task Manager</h1>
          <p>Run ID: {runId}</p>
        </div>
        <div className="filters">
          <label htmlFor="status-filter">Filter</label>
          <select
            id="status-filter"
            value={filter}
            onChange={(event) => setFilter(event.target.value as StatusFilter)}
          >
            <option value="all">All</option>
            <option value="todo">Todo</option>
            <option value="done">Done</option>
          </select>
        </div>
      </header>

      <form className="task-form" onSubmit={handleSubmit}>
        <input
          type="text"
          placeholder="Add a task"
          value={text}
          onChange={(event) => setText(event.target.value)}
        />
        <button type="submit">Add</button>
      </form>

      <main>
        {!tasks && <p className="loading">Loading tasks...</p>}
        {tasks && tasks.length === 0 && (
          <p className="empty">No tasks yet. Add one above.</p>
        )}
        <ul className="task-list">
          {tasks?.map((task) => (
            <li key={task._id} className={task.status === 'done' ? 'done' : ''}>
              <div>
                <p>{task.text}</p>
                <span className="status">{task.status}</span>
              </div>
              <div className="actions">
                <button
                  type="button"
                  onClick={() =>
                    updateTaskStatus({
                      id: task._id,
                      status: task.status === 'todo' ? 'done' : 'todo',
                    })
                  }
                >
                  Toggle
                </button>
                <button
                  type="button"
                  className="delete"
                  onClick={() => deleteTask({ id: task._id })}
                >
                  Delete
                </button>
              </div>
            </li>
          ))}
        </ul>
      </main>
    </div>
  )
}

export default App

